"""Présentation commune, embarquée dans les rapports HTML autonomes."""
CSS = '''
:root{color-scheme:dark;--fond:#0c1018;--carte:#171e2c;--texte:#f3f6ff;--doux:#aab6ca;--bord:#ffffff18;--achat:#71deb1;--gain:#71deb1;--vente:#ff919e;--perte:#ff919e;--sortir:#f2c777;--serie:#80b7ff;--grille:#ffffff0c}
*{box-sizing:border-box}html{background:var(--fond)}body{margin:0;background:radial-gradient(ellipse at 15% 0,#243c5b66,transparent 55%),var(--fond);color:var(--texte);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100vh;-webkit-font-smoothing:antialiased}
main{max-width:1040px;margin:auto;padding:calc(28px + env(safe-area-inset-top)) 20px calc(110px + env(safe-area-inset-bottom))}h1{font-size:clamp(30px,6vw,42px);letter-spacing:-1.2px;margin:10px 0}h2{font-size:21px;margin-top:28px}h3{font-size:15px}a{color:#a6cbff}button,select,summary,a{touch-action:manipulation}button,select{min-height:44px}button,select,summary{cursor:pointer}a:focus-visible,button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #80b7ff;outline-offset:3px}
.carte,section,.hero-panel{background:linear-gradient(125deg,#ffffff09,transparent),var(--carte);border:1px solid var(--bord);border-radius:24px;padding:22px;margin:14px 0;box-shadow:0 14px 42px #0002;overflow-wrap:anywhere}.carte.achat{border-left:3px solid var(--achat)}.carte.vente{border-left:3px solid var(--vente)}.carte.sortir{border-left:3px solid var(--sortir)}.marche{gap:4px 10px;font-size:18px}.marche span{font-size:12px;flex-basis:100%}.statut{font-size:18px;margin:12px 0 8px}.detail{line-height:1.7;font-size:14px}.sous,.note{line-height:1.7}.suivie{color:#9fc4ff;letter-spacing:.04em;margin-bottom:12px}.badge{padding:4px 9px;border-radius:9px;background:#ffffff08;font-size:11px}.hero-panel{background:linear-gradient(115deg,#27466c,#192638);padding:26px}.eyebrow{color:#a9caff;font-size:11px;text-transform:uppercase;font-weight:700;letter-spacing:.14em}.hero-panel h2{margin:8px 0;font-size:25px}.hero-panel p{margin:8px 0;color:#c2d0e4}.hero-panel strong{color:#fff}.resume{font-weight:400}.filtres{background:#0c1018ed;backdrop-filter:blur(20px);padding:12px 0;gap:8px}.filtres button,.filtres select{border:1px solid var(--bord);background:#202b3d;border-radius:14px;padding:10px 14px;font-size:14px}.filtres button[aria-pressed="true"]{background:#9cc8ff;color:#102037;border-color:transparent}.filtres select{max-width:100%;color:var(--texte)}.validation{border-top:1px solid var(--bord);margin-top:16px;color:var(--doux);font-size:13px}.validation summary{padding:14px 0;min-height:44px;color:#abd0ff}.validation ul{padding-left:18px}.demo{background:#4b3e22;color:#ffe1a1;border-radius:14px;padding:14px}.tuiles{gap:12px}.tuile{background:#ffffff05;border-radius:16px;padding:16px;min-width:0}.valeur{font-size:clamp(32px,8vw,52px);letter-spacing:-1.5px}.positions .haut{flex-wrap:wrap}.defile{max-width:100%;overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--bord);white-space:nowrap}th{color:var(--doux)}.bottom-nav{position:fixed;bottom:12px;bottom:calc(12px + env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);display:flex;gap:6px;padding:7px;background:#1b2639ed;backdrop-filter:blur(24px);border:1px solid #ffffff24;border-radius:23px;box-shadow:0 10px 40px #0008;z-index:10;width:min(360px,calc(100% - 28px))}.bottom-nav a{flex:1;text-align:center;padding:10px 12px;border-radius:16px;min-height:44px;text-decoration:none;font-size:14px;color:#b6c5dc}.bottom-nav a[aria-current="page"]{background:#a6ceff;color:#13233b;font-weight:600}.kpis{display:flex;gap:26px;flex-wrap:wrap}.kpis b{display:block;font-size:25px;color:var(--texte)}.kpis span{font-size:12px;color:var(--doux)}
@media(min-width:800px){main{padding-top:42px}.carte{padding:24px}.bottom-nav{bottom:22px}.hero-panel{padding:32px}.filtres select{margin-left:auto}}
@media(max-width:380px){main{padding-left:12px;padding-right:12px}.carte,section{padding:17px}.filtres select{margin-left:0;width:100%}.valeur{font-size:34px}}
'''


def navigation(page):
    return ('<nav class="bottom-nav" aria-label="Navigation principale">' + ''.join(
        f'<a href="{href}"' + (' aria-current="page"' if page == key else '') + f'>{label}</a>'
        for key, href, label in [('signaux', 'index.html', '◈ Signaux'), ('bot', 'bot.html', '◉ Portefeuille')]) + '</nav>')
